#!/usr/bin/env bash
# init-dev-environment installer, generated by the claude-code-knowledge
# repository-audit skill. Usage: bash install.sh [--dry-run] <tool-id>...
# Prints one line per tool: present: | missing: (dry-run) | installed: |
# FAILED: <id>, plus a note: line. Exit 0 = all ok, 1 = a tool failed.
# User level only (never sudo). Binaries land in, or are symlinked into,
# ~/.local/bin. A tool that is already usable is never reinstalled.
set -u
DRY=0
if [ "${1:-}" = "--dry-run" ]; then
  DRY=1
  shift
fi
BIN="$HOME/.local/bin"
CARGO_BIN="${CARGO_HOME:-$HOME/.cargo}/bin"
ORIG_PATH="${PATH:-}"
export PATH="${PATH:+$PATH:}$BIN:$CARGO_BIN:$HOME/.bun/bin" # append: inherited PATH wins
FAILED=0
INSTALLED=0

os() { uname -s | tr '[:upper:]' '[:lower:]'; } # linux | darwin
arch() {
  case "$(uname -m)" in
    x86_64 | amd64) echo x64 ;;
    aarch64 | arm64) echo arm64 ;;
    *)
      echo "unsupported architecture: $(uname -m)" >&2
      return 1
      ;;
  esac
}
sha256() { if command -v sha256sum > /dev/null 2>&1; then sha256sum "$@"; else shasum -a 256 "$@"; fi; }

# <path>: 0 when nothing is there; a dangling symlink is removed first
vacant() {
  if [ -L "$1" ] && [ ! -e "$1" ]; then rm -f "$1" || return 1; fi
  [ ! -e "$1" ]
}
link() {
  vacant "$BIN/${1##*/}" || return 0
  ln -s "$1" "$BIN/${1##*/}"
} # never clobber

# <id>: 0 when the tool is usable. The single probe for the dry-run plan and
# the post-install check, so both always agree.
present() {
  case "$1" in
    # rustup ships a ~/.cargo/bin/rust-analyzer proxy that exists without the
    # component and exits non-zero, so command -v is not enough
    rust-analyzer) rust-analyzer --version > /dev/null 2>&1 ;;
    *) command -v "$1" > /dev/null 2>&1 ;;
  esac
}

ensure() { # <id>: present | missing (dry-run) | installed | FAILED
  local id="$1" fn="install_${1//-/_}"
  if ! declare -F "$fn" > /dev/null; then
    echo "FAILED: $id (unknown tool id)"
    return 1
  fi
  if present "$id"; then
    echo "present: $id"
    return 0
  fi
  if [ "$DRY" = 1 ]; then
    echo "missing: $id"
    return 0
  fi
  if mkdir -p "$BIN" && "$fn" && present "$id"; then
    echo "installed: $id"
    INSTALLED=1
    return 0
  fi
  echo "FAILED: $id"
  return 1
}

# install_<id> recipes. Each chains its steps with && (no set -e: bash ignores
# it inside a function run from an if/&& list), guards every version lookup
# against an empty answer, and removes its temp dir on success and failure.
# A recipe that needs a runtime starts with `ensure <dep> &&`.
# ponytail: the download recipes (node, go, bun, cargo, uv, lua-language-server)
# hard-code upstream URLs and are covered only by bash -n, the id/function
# parity check and the no-sudo grep; upgrade path: a base-URL override plus a
# local node:http fixture server, as in rtk-install.bats.

install_node() {
  local a v f tmp rc d="$HOME/.local/share/node"
  a=$(arch) || return 1
  v=$(curl -fsSL https://nodejs.org/dist/index.tab | awk -F'\t' 'NR>1 && $10!="-" {print $1; exit}')
  [ -n "$v" ] || return 1
  f="node-$v-$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  curl -fsSL -o "$tmp/$f" "https://nodejs.org/dist/$v/$f" \
    && curl -fsSL "https://nodejs.org/dist/$v/SHASUMS256.txt" | grep " $f\$" | (cd "$tmp" && sha256 -c -) \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" --strip-components=1 \
    && link "$d/bin/node" && link "$d/bin/npm" && link "$d/bin/npx"
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

install_pnpm() { ensure node && npm install -g --prefix "$HOME/.local" pnpm; }

install_yarn() { ensure node && npm install -g --prefix "$HOME/.local" yarn; }

# bun's installer puts the binary in $BUN_INSTALL/bin and skips every rc-file
# edit when `command -v bun` resolves (it does: PATH includes ~/.local/bin).
install_bun() { curl -fsSL https://bun.sh/install | BUN_INSTALL="$HOME/.local" bash; }

install_cargo() {
  curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --no-modify-path \
    && link "$CARGO_BIN/cargo" && link "$CARGO_BIN/rustc" && link "$CARGO_BIN/rustup"
}

install_rust_analyzer() { ensure cargo && rustup component add rust-analyzer && link "$CARGO_BIN/rust-analyzer"; }

install_go() {
  local a v f tmp rc d="$HOME/.local/share"
  a=$(arch) || return 1
  if [ "$a" = x64 ]; then a=amd64; fi
  v=$(curl -fsSL 'https://go.dev/VERSION?m=text' | head -n1)
  [ -n "$v" ] || return 1
  f="$v.$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  curl -fsSL -o "$tmp/$f" "https://dl.google.com/go/$f" \
    && echo "$(curl -fsSL "https://dl.google.com/go/$f.sha256")  $tmp/$f" | sha256 -c - \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" \
    && link "$d/go/bin/go" && link "$d/go/bin/gofmt"
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

install_gopls() { ensure go && GOBIN="$BIN" go install golang.org/x/tools/gopls@latest; }

install_uv() { curl -LsSf https://astral.sh/uv/install.sh | env UV_INSTALL_DIR="$BIN" UV_NO_MODIFY_PATH=1 sh; }

install_python3() { ensure uv && UV_PYTHON_BIN_DIR="$BIN" uv python install --default; }

install_pylsp() { ensure uv && UV_TOOL_BIN_DIR="$BIN" uv tool install python-lsp-server; }

# LuaLS publishes no checksums (HTTPS only); its tarball is flat (bin/,
# main.lua, ... at the root), so it gets a wrapper rather than a symlink.
install_lua_language_server() {
  local a t f tmp rc d="$HOME/.local/share/lua-language-server" w="$BIN/lua-language-server"
  a=$(arch) || return 1
  t=$(curl -fsSLI -o /dev/null -w '%{url_effective}' https://github.com/LuaLS/lua-language-server/releases/latest)
  t=${t##*/}
  [ -n "$t" ] || return 1
  f="lua-language-server-$t-$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  curl -fsSL -o "$tmp/$f" "https://github.com/LuaLS/lua-language-server/releases/download/$t/$f" \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" \
    && if vacant "$w"; then
      printf '%s\n' '#!/usr/bin/env bash' 'exec "$HOME/.local/share/lua-language-server/bin/lua-language-server" "$@"' > "$w" && chmod 755 "$w"
    fi
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

for id in "$@"; do ensure "$id" || FAILED=1; done
if [ "$INSTALLED" = 1 ]; then
  case ":$ORIG_PATH:" in *":$BIN:"*) ;; *) echo "note: $BIN is not on PATH; add it to your shell profile" ;; esac
fi
exit "$FAILED"
